package com.vandorlabs.neoforge.screen;
import com.google.gson.*;
import com.vandorlabs.screen.*;
import net.minecraft.core.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.*;
/** Actual native physical probes reproduce Source cache phases; automatic host propagation is separate. */
final class ScreenJoinedPowerChecks {
 private static Block probe;private static int strength,reads;
 @net.neoforged.fml.common.EventBusSubscriber(modid="vandorlabs",bus=net.neoforged.fml.common.EventBusSubscriber.Bus.MOD)public static final class Registration{
  @net.neoforged.bus.api.SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent event){if(!System.getProperty("vandorlabs.transmitterPhase","").startsWith("screen-block"))return;event.register(net.minecraft.core.registries.Registries.BLOCK,h->{probe=new Block(BlockBehaviour.Properties.of().noOcclusion().isRedstoneConductor((s,w,p)->false)){@Override protected int getSignal(BlockState state,BlockGetter world,BlockPos pos,Direction side){reads++;return strength;}};h.register(net.minecraft.resources.ResourceLocation.parse("vandorlabs:screen_power_cache_probe"),probe);});}
 }
 static void run(ServerLevel level,java.util.Map<ScreenFamily,NativeScreenBlock> blocks)throws Exception{JsonObject reference;try(var reader=java.nio.file.Files.newBufferedReader(java.nio.file.Path.of(System.getProperty("screenJoinedPowerReference")))){reference=JsonParser.parseReader(reader).getAsJsonObject();}int cases=0;for(var entry:reference.getAsJsonArray("cases")){var row=entry.getAsJsonObject();var family=ScreenFamily.fromId(row.get("id").getAsString());var block=blocks.get(family);var state=block.state(family.decode(row.get("meta").getAsInt()));var basis=ScreenJoinGeometry.basis(family,block.screenState(state),false);var tiles=new NativeScreenEntity[2];var base=new BlockPos(4480,110,4480);for(int i=0;i<2;i++){var pos=base.offset(i*basis.dx(0),i*basis.dy(0),i*basis.dz(0));level.getChunkAt(pos);level.setBlock(pos,state,2);tiles[i]=(NativeScreenEntity)level.getBlockEntity(pos);var settings=new CompoundTag();new NativeScreenActivation(com.vandorlabs.persistence.DisplayActivationData.LEGACY.withMode(row.get("mode").getAsInt())).write(settings);settings.putBoolean("RedstoneInverted",row.get("inverted").getAsBoolean());tiles[i].loadWithComponents(settings,level.registryAccess());level.setBlock(pos.above(),probe.defaultBlockState(),2);NativeScreenJoinedPower.changed(tiles[i]);}var actual=new JsonArray();strength=0;actual.add(sample(tiles));strength=7;int beforeReads=reads;actual.add(sample(tiles));if(row.get("mode").getAsInt()>0&&ScreenJoinGeometry.supports(family,false)&&reads!=beforeReads)throw new AssertionError("warm same-tick joined cache rescans physical neighbors");((net.minecraft.world.level.storage.ServerLevelData)level.getLevelData()).setGameTime(level.getGameTime()+1);actual.add(sample(tiles));strength=12;NativeScreenJoinedPower.inputChanged(tiles[1]);actual.add(sample(tiles));tiles[0].setChannelLevel(15);strength=0;NativeScreenJoinedPower.inputChanged(tiles[0]);actual.add(sample(tiles));NativeScreenJoinedPower.changed(tiles[1]);level.setBlock(tiles[1].getBlockPos(),Blocks.AIR.defaultBlockState(),2);strength=5;actual.add(sample(new NativeScreenEntity[]{tiles[0]}));if(!actual.equals(row.get("phases")))throw new AssertionError("Actual native Source cache mismatch case="+cases+" actual="+actual+" expected="+row.get("phases"));for(var tile:tiles){NativeScreenJoinedPower.changed(tile);level.setBlock(tile.getBlockPos(),Blocks.AIR.defaultBlockState(),2);level.setBlock(tile.getBlockPos().above(),Blocks.AIR.defaultBlockState(),2);}cases++;}if(cases!=420||!reference.get("sha256").getAsString().equals("29e237d5369446fbf21212fed41a3757a1ef8d18e8a0b1499a6e2ae77e11382d"))throw new AssertionError("Source joined power coverage");System.out.println("Native Screen joined physical power cache PASS actual Source="+cases+" warm same-tick probe reads=0; group publication checked separately");}
 private static JsonArray sample(NativeScreenEntity[] tiles){var out=new JsonArray();for(var tile:tiles){var value=new JsonArray();value.add(NativeScreenJoinedPower.level(tile));value.add(Math.max(tile.screenSettings().channelLevel(),NativeScreenJoinedPower.level(tile)));out.add(value);}return out;}
}
